package com.shatteredpixel.shatteredpixeldungeon.mod;
import com.watabou.utils.Bundle; import com.shatteredpixel.shatteredpixeldungeon.Dungeon; import com.shatteredpixel.shatteredpixeldungeon.items.Item; import com.shatteredpixel.shatteredpixeldungeon.items.potions.Potion; import com.shatteredpixel.shatteredpixeldungeon.items.scrolls.Scroll; import com.shatteredpixel.shatteredpixeldungeon.items.rings.Ring;
public final class ModHooks { private ModHooks(){} public static void tick(){if(Dungeon.level!=null&&Dungeon.hero!=null)ModRegistry.tick(Dungeon.level,Dungeon.hero.pos);} public static void picked(Item i){ModRegistry.picked(i);} public static int gold(int n){return ModRegistry.modifyGold(n);} public static boolean identified(Item i,boolean v){return ModRegistry.identified(i,v);} public static boolean known(Potion i,boolean v){return ModRegistry.identified(i,v);} public static boolean known(Scroll i,boolean v){return ModRegistry.identified(i,v);} public static boolean known(Ring i,boolean v){return ModRegistry.identified(i,v);} public static void store(Bundle b){ModRegistry.store(b);} public static void restore(Bundle b){ModRegistry.restore(b);} }
